 for(let index=0;index<retained.length;index++)builder[retained[index][0]]=outcomes[index];
 builder.joined=retained.length===3&&builder.returned===builder.original&&builder.internalObserverAssociated===true;
}
function classifyBuilderCustody(builder){
 // Proof: removing actual observer outcome checks admitted a rejected internal observer; round1 inert custody consumer failed, restoration passed.
 // Proof: removing callEntered===false in a copied helper admitted a pre-call state with an entered marker; round1 inert control failed and restoration passed.
 if(builder.callEntered===false&&builder.state==='not-entered'&&builder.original===undefined&&builder.observer===undefined&&builder.internalObserver===undefined&&builder.originalOutcome===undefined&&builder.driverObserverOutcome===undefined&&builder.internalObserverOutcome===undefined)return {known:true,branch:'call-not-entered'};
 if(builder.callEntered!==true||builder.joined!==true||!(builder.original instanceof Promise)||!(builder.observer instanceof Promise)||!(builder.internalObserver instanceof Promise)||builder.returned!==builder.original||builder.internalObserverAssociated!==true)return {known:false,branch:'association-or-join-unknown'};
 if(builder.originalOutcome===undefined||!['fulfilled','rejected'].includes(builder.originalOutcome.status)||builder.driverObserverOutcome?.status!=='fulfilled'||builder.internalObserverOutcome?.status!=='fulfilled')return {known:false,branch:'observer-settlement-unknown'};
