const index=kind=>associations.findIndex(edge=>edge.representation===kind);
const direct=associations.findIndex(edge=>edge.representation==='direct'&&edge.rawPath.startsWith('ordinary-hold-v1:')),node=index('node-prefix'),historical=index('historical-relative');
const scanner=associations.findIndex(edge=>edge.identity.endsWith('/dependency-migration-artifact-scanner.ts'));
