 ['historical destination',c=>{const g=structuredClone(coverage);g.rows.find(row=>row.identity===associations[historical].importerIdentity).imports.find(edge=>edge.specifier===raw[historical].rawPath).destination=root+'/forged.js';return evaluate(c,raw,g);}],
 ['scanner foreign',c=>evaluate(c,change(scanner,{rawPath:root+'/forged-scanner.js'}))],
 ['scanner bundled',c=>evaluate(c,change(scanner,{external:false}))],
 ['different cwd',c=>evaluate(c,[{...raw[scanner],rawImporter:entry}],coverage,closure,contract,'/tmp')],
 ['present undefined original',c=>evaluate(c,change(historical,{original:undefined}))],
