 ['ambiguous semantics',c=>{const g=structuredClone(coverage);const row=g.rows.find(row=>row.identity===associations[historical].importerIdentity);const edge=row.imports.find(edge=>edge.specifier===raw[historical].rawPath);row.imports.push({...edge,destination:edge.specifier,external:true});return evaluate(c,raw,g);}],
